await s.set("a", 1, 1e4); await s.set("b", 2, 1e4); await s.get("a"); await s.set("c", 3, 1e4);
assert.equal(await s.get("b"), undefined); assert.equal(await s.get("a"), 1); assert.equal(await s.get("c"), 3);
console.log("all passed");
